-- ================= supabase/migrations/0008_storage.sql =================
-- Pemart 0008: Storage buckets and policies (skipped cleanly if storage schema is absent)
do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'storage schema not found; skipping bucket setup';
    return;
  end if;

  insert into storage.buckets (id, name, public) values
    ('product-images', 'product-images', true),     -- catalogue photos, public CDN
    ('review-photos',  'review-photos',  true),      -- customer review photos (random paths)
    ('design-uploads', 'design-uploads', false),     -- customer references and sketches
    ('proofs',         'proofs',         false),     -- design proofs sent to customers
    ('print-artwork',  'print-artwork',  false),     -- print-ready files
    ('bulk-uploads',   'bulk-uploads',   false)
  on conflict (id) do nothing;

  execute $p$create policy "public read catalogue images" on storage.objects
    for select using (bucket_id in ('product-images','review-photos'))$p$;
  execute $p$create policy "admin manage catalogue images" on storage.objects
    for all using (bucket_id = 'product-images' and public.is_admin())
    with check (bucket_id = 'product-images' and public.is_admin())$p$;
  -- Signed-in customers upload only into their own folder: <uid>/<file>
  execute $p$create policy "customer upload own design files" on storage.objects
    for insert to authenticated
    with check (bucket_id = 'design-uploads' and (storage.foldername(name))[1] = auth.uid()::text)$p$;
  execute $p$create policy "customer read own design files" on storage.objects
    for select to authenticated
    using (bucket_id = 'design-uploads' and (storage.foldername(name))[1] = auth.uid()::text)$p$;
  execute $p$create policy "staff read private files" on storage.objects
    for select using (bucket_id in ('design-uploads','proofs','print-artwork','bulk-uploads') and public.is_staff())$p$;
  execute $p$create policy "staff write proofs and artwork" on storage.objects
    for insert with check (bucket_id in ('proofs','print-artwork') and public.is_staff())$p$;
  -- Guest uploads (bulk quotes, guest custom orders) go through server routes
  -- using signed upload URLs created with the service role.
end $$;

-- ================= supabase/migrations/0009_bundle_visibility.sql =================
-- Pemart 0009: show expired bundles to the storefront so pages can explain
-- "this gift box has ended" instead of a bare 404. Availability is enforced in
-- application code (hub, bundle page) and, authoritatively, by the checkout
-- server, which re-validates every bundle before creating an order.
drop policy if exists bundles_read on public.bundles;
drop policy if exists slots_read on public.bundle_slots;

create policy bundles_read on public.bundles for select
  using (is_active or public.is_staff());
create policy slots_read on public.bundle_slots for select
  using (public.is_staff() or exists (
    select 1 from public.bundles b where b.id = bundle_id and b.is_active));

-- ================= supabase/migrations/0010_checkout.sql =================
-- Pemart 0010: checkout. Money-critical steps run as single-transaction SQL functions.
-- Every function takes ONE jsonb argument `p`, is SECURITY DEFINER, and is executable by
-- the service role only (never by anon or signed-in browsers).

alter table public.orders
  add column if not exists public_token text not null default encode(gen_random_bytes(16), 'hex'),
  add column if not exists reservations jsonb not null default '[]'::jsonb,   -- [{variant_id, qty}] stocked items held for this order
  add column if not exists surprise_note boolean not null default false,
  add column if not exists payment_note text;
create unique index if not exists orders_public_token_idx on public.orders(public_token);

alter table public.order_items drop constraint if exists order_items_kind_check;
alter table public.order_items add constraint order_items_kind_check check (kind in ('variant','bundle','gift_card','custom'));

-- ---------------------------------------------------------------- helpers
create or replace function public._gift_code() returns text language plpgsql as $$
declare chars text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; code text := ''; i int;
begin
  for i in 1..12 loop code := code || substr(chars, 1 + floor(random() * length(chars))::int, 1); end loop;
  return 'PG-' || substr(code,1,4) || '-' || substr(code,5,4) || '-' || substr(code,9,4);
end $$;

-- Put back stock holds, store credit and gift card balance for an unpaid order.
create or replace function public._release_order(p_order uuid) returns void language plpgsql as $$
declare o public.orders; r jsonb;
begin
  select * into o from public.orders where id = p_order;
  for r in select * from jsonb_array_elements(o.reservations) loop
    update public.product_variants
       set reserved_qty = greatest(0, reserved_qty - (r->>'qty')::int)
     where id = (r->>'variant_id')::uuid;
  end loop;
  if o.credit_used_kobo > 0 and o.profile_id is not null then
    update public.profiles set store_credit_kobo = store_credit_kobo + o.credit_used_kobo where id = o.profile_id;
  end if;
  if o.gift_card_used_kobo > 0 and o.gift_card_id is not null then
    update public.gift_cards set balance_kobo = balance_kobo + o.gift_card_used_kobo where id = o.gift_card_id;
  end if;
end $$;

-- ---------------------------------------------------------------- lookups for pricing
create or replace function public.checkout_context(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare d public.discount_codes; amb public.ambassadors; gc public.gift_cards; uses int := 0; credit bigint := 0; out jsonb := '{}'::jsonb;
begin
  if coalesce(p->>'code','') <> '' then
    select * into d from public.discount_codes where upper(code) = upper(p->>'code') and is_active;
    if found then
      select count(*) into uses from public.orders o
       where o.discount_code_id = d.id and o.status not in ('cancelled','pending_payment','refunded')
         and ((p->>'profile_id' is not null and o.profile_id = (p->>'profile_id')::uuid)
              or (p->>'email' is not null and lower(o.contact_email) = lower(p->>'email')));
      select * into amb from public.ambassadors where id = d.ambassador_id and is_active;
      out := out || jsonb_build_object('discount', jsonb_build_object(
        'id', d.id, 'code', d.code, 'type', d.type, 'value', d.value, 'min_spend_kobo', d.min_spend_kobo,
        'starts_at', d.starts_at, 'ends_at', d.ends_at, 'usage_limit', d.usage_limit, 'times_used', d.times_used,
        'per_customer_limit', d.per_customer_limit, 'customer_uses', uses,
        'collection_ids', d.collection_ids, 'product_ids', d.product_ids,
        'ambassador_id', d.ambassador_id, 'ambassador_rate', amb.commission_rate));
    end if;
  end if;
  if coalesce(p->>'gift_code','') <> '' then
    select * into gc from public.gift_cards where upper(code) = upper(p->>'gift_code');
    if found then
      out := out || jsonb_build_object('gift_card', jsonb_build_object('id', gc.id, 'code', gc.code, 'balance_kobo', gc.balance_kobo, 'expires_at', gc.expires_at));
    end if;
  end if;
  if p->>'profile_id' is not null then
    select store_credit_kobo into credit from public.profiles where id = (p->>'profile_id')::uuid;
    out := out || jsonb_build_object('credit_kobo', coalesce(credit, 0));
  end if;
  return out;
end $$;

-- ---------------------------------------------------------------- custom requests
create or replace function public.custom_request_create(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare did uuid; rid uuid;
begin
  if coalesce(p->>'design_slug','') <> '' then select id into did from public.designs where slug = p->>'design_slug'; end if;
  insert into public.custom_requests (profile_id, contact_email, tier, product_type, design_id, colour, print_positions, text_fields, type_style, notes, upload_paths, status, fee_kobo)
  values ((p->>'profile_id')::uuid, p->>'contact_email', p->>'tier', p->>'product_type', did, p->>'colour',
          coalesce(array(select jsonb_array_elements_text(p->'print_positions')), '{back}'),
          coalesce(p->'text_fields', '{}'::jsonb), p->>'type_style', p->>'notes',
          coalesce(array(select jsonb_array_elements_text(p->'upload_paths')), '{}'), 'draft', (p->>'fee_kobo')::bigint)
  returning id into rid;
  return jsonb_build_object('id', rid);
end $$;

-- Requests usable in a new order: still draft and not attached to a live order.
create or replace function public.checkout_custom_requests(p jsonb) returns jsonb
language sql security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'tier', c.tier, 'product_type', c.product_type, 'colour', c.colour, 'status', c.status,
    'text_fields', c.text_fields, 'type_style', c.type_style, 'design_id', c.design_id, 'print_positions', c.print_positions,
    'in_use', exists (select 1 from public.order_items oi join public.orders o on o.id = oi.order_id
                      where oi.custom_request_id = c.id and o.status not in ('cancelled'))
  )), '[]'::jsonb)
  from public.custom_requests c
  where c.id in (select (jsonb_array_elements_text(p->'ids'))::uuid)
$$;

-- ---------------------------------------------------------------- create order (atomic)
create or replace function public.checkout_create_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  it jsonb; rv jsonb; v public.product_variants; oid uuid; onum text; tok text; res jsonb := '[]'::jsonb; n int;
begin
  -- 1. Reserve stock for stocked variants. Row locks serialise competing buyers.
  for rv in select * from jsonb_array_elements(coalesce(p->'reserve','[]'::jsonb)) loop
    select * into v from public.product_variants where id = (rv->>'variant_id')::uuid for update;
    if not found or not v.is_active then raise exception 'unavailable:%', coalesce(rv->>'variant_id','?'); end if;
    if v.stock_qty is not null then
      if v.stock_qty - v.reserved_qty < (rv->>'qty')::int then raise exception 'out_of_stock:%', v.sku; end if;
      update public.product_variants set reserved_qty = reserved_qty + (rv->>'qty')::int where id = v.id;
      res := res || jsonb_build_array(jsonb_build_object('variant_id', v.id, 'qty', (rv->>'qty')::int));
    end if;
  end loop;

  -- 2. Hold store credit and gift card balance (restored if the order is cancelled).
  if coalesce((p->>'credit_used')::bigint, 0) > 0 then
    update public.profiles set store_credit_kobo = store_credit_kobo - (p->>'credit_used')::bigint
     where id = (p->>'profile_id')::uuid and store_credit_kobo >= (p->>'credit_used')::bigint;
    get diagnostics n = row_count; if n = 0 then raise exception 'insufficient_credit'; end if;
  end if;
  if coalesce((p->>'gift_card_used')::bigint, 0) > 0 then
    update public.gift_cards set balance_kobo = balance_kobo - (p->>'gift_card_used')::bigint
     where id = (p->>'gift_card_id')::uuid and balance_kobo >= (p->>'gift_card_used')::bigint and (expires_at is null or expires_at > now());
    get diagnostics n = row_count; if n = 0 then raise exception 'gift_card_unavailable'; end if;
  end if;

  -- 3. The order, its items, first event and the payment record.
  insert into public.orders (profile_id, contact_email, contact_phone, status, has_custom, has_bundle,
      subtotal_kobo, discount_kobo, delivery_fee_kobo, gift_wrap_kobo, surprise_note_kobo, express_kobo, ship_ready_first_kobo,
      credit_used_kobo, gift_card_used_kobo, total_kobo, address, delivery_zone_id, delivery_zone_name, is_gift, gift_message,
      ship_ready_first, express, surprise_note, discount_code_id, discount_code, ambassador_code, gift_card_id,
      payment_reference, expires_at, reservations)
  values ((p->>'profile_id')::uuid, p->>'contact_email', p->>'contact_phone', 'pending_payment',
      coalesce((p->>'has_custom')::boolean,false), coalesce((p->>'has_bundle')::boolean,false),
      (p->>'subtotal')::bigint, (p->>'discount')::bigint, (p->>'delivery_fee')::bigint, (p->>'gift_wrap')::bigint,
      (p->>'surprise_note_fee')::bigint, (p->>'express_fee')::bigint, (p->>'ship_ready_first_fee')::bigint,
      (p->>'credit_used')::bigint, (p->>'gift_card_used')::bigint, (p->>'total')::bigint,
      p->'address', (p->>'delivery_zone_id')::uuid, p->>'delivery_zone_name', coalesce((p->>'is_gift')::boolean,false), p->>'gift_message',
      coalesce((p->>'ship_ready_first')::boolean,false), coalesce((p->>'express')::boolean,false), coalesce((p->>'surprise_note')::boolean,false),
      (p->>'discount_code_id')::uuid, p->>'discount_code', p->>'ambassador_code', (p->>'gift_card_id')::uuid,
      p->>'payment_reference', coalesce((p->>'expires_at')::timestamptz, now() + interval '24 hours'), res)
  returning id, number, public_token into oid, onum, tok;

  for it in select * from jsonb_array_elements(p->'items') loop
    insert into public.order_items (order_id, kind, variant_id, bundle_id, name, options, selections, unit_price_kobo, quantity, custom_request_id, gift_message)
    values (oid, it->>'kind', (it->>'variant_id')::uuid, (it->>'bundle_id')::uuid, it->>'name', coalesce(it->'options','{}'::jsonb),
            it->'selections', (it->>'unit_price')::bigint, (it->>'quantity')::int, (it->>'custom_request_id')::uuid, it->>'gift_message');
  end loop;

  insert into public.order_events (order_id, status, note) values (oid, 'pending_payment', 'Order created');
  insert into public.payments (order_id, provider, reference, amount_kobo, currency, status)
  values (oid, 'paystack', p->>'payment_reference', (p->>'total')::bigint, 'NGN', 'initialised');

  return jsonb_build_object('order_id', oid, 'number', onum, 'token', tok, 'total', (p->>'total')::bigint, 'reference', p->>'payment_reference');
end $$;

-- ---------------------------------------------------------------- mark paid (idempotent)
create or replace function public.checkout_mark_paid(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  o public.orders; pay public.payments; z public.delivery_zones; amb public.ambassadors; r jsonb; v public.product_variants;
  item record; lead int; start_at timestamptz := now(); final text; codes jsonb := '[]'::jsonb; gc text; i int; sub_for_commission bigint;
begin
  select * into o from public.orders where payment_reference = p->>'reference' for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'unknown_reference'); end if;
  select * into pay from public.payments where reference = p->>'reference' for update;

  -- Idempotency: a second call (webhook retry, verify + webhook race) changes nothing.
  if pay.status = 'success' then
    return jsonb_build_object('ok', true, 'already', true, 'order_id', o.id, 'number', o.number, 'status', o.status, 'token', o.public_token);
  end if;

  -- Never trust the client or the network: the amount and currency must match what we charged.
  if (p->>'amount')::bigint is distinct from o.total_kobo or coalesce(p->>'currency','NGN') <> 'NGN' then
    update public.payments set status = 'failed', raw_payload = p->'payload' where id = pay.id;
    insert into public.order_events (order_id, status, note) values (o.id, o.status, 'Payment rejected: amount or currency mismatch');
    return jsonb_build_object('ok', false, 'error', 'amount_mismatch', 'order_id', o.id);
  end if;

  if o.status = 'cancelled' then
    -- Paid after the order lapsed: take the hold again if we still can, otherwise flag it for a refund.
    begin
      for r in select * from jsonb_array_elements(o.reservations) loop
        select * into v from public.product_variants where id = (r->>'variant_id')::uuid for update;
        if v.stock_qty - v.reserved_qty < (r->>'qty')::int then raise exception 'out_of_stock'; end if;
        update public.product_variants set reserved_qty = reserved_qty + (r->>'qty')::int where id = v.id;
      end loop;
      -- credit and gift card were released at cancellation; take them again
      if o.credit_used_kobo > 0 then update public.profiles set store_credit_kobo = store_credit_kobo - o.credit_used_kobo where id = o.profile_id and store_credit_kobo >= o.credit_used_kobo; if not found then raise exception 'credit'; end if; end if;
      if o.gift_card_used_kobo > 0 then update public.gift_cards set balance_kobo = balance_kobo - o.gift_card_used_kobo where id = o.gift_card_id and balance_kobo >= o.gift_card_used_kobo; if not found then raise exception 'gift'; end if; end if;
    exception when others then
      update public.payments set status = 'success', verified_at = now(), raw_payload = p->'payload' where id = pay.id;
      update public.orders set payment_note = 'Paid after the order expired and could not be restored. Refund needed.' where id = o.id;
      insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', 'Payment received after expiry; could not restore stock. Refund needed.');
      return jsonb_build_object('ok', true, 'needs_refund', true, 'order_id', o.id, 'number', o.number, 'status', 'cancelled', 'token', o.public_token);
    end;
  end if;

  update public.payments set status = 'success', verified_at = now(), raw_payload = p->'payload' where id = pay.id;

  -- Stock: turn the hold into a real decrement.
  for r in select * from jsonb_array_elements(o.reservations) loop
    update public.product_variants
       set stock_qty = stock_qty - (r->>'qty')::int, reserved_qty = greatest(0, reserved_qty - (r->>'qty')::int)
     where id = (r->>'variant_id')::uuid and stock_qty is not null;
  end loop;

  if o.discount_code_id is not null then update public.discount_codes set times_used = times_used + 1 where id = o.discount_code_id; end if;

  -- Ambassador commission: rate x goods subtotal, recorded once per order.
  if o.ambassador_code is not null then
    select a.* into amb from public.ambassadors a where upper(a.code) = upper(o.ambassador_code);
    if found then
      sub_for_commission := o.subtotal_kobo;
      insert into public.commissions (ambassador_id, order_id, amount_kobo, status)
      values (amb.id, o.id, round(sub_for_commission * amb.commission_rate)::bigint, 'pending') on conflict (order_id) do nothing;
    end if;
  end if;

  -- Gift cards bought in this order: create the codes.
  for item in select * from public.order_items where order_id = o.id and kind = 'gift_card' loop
    for i in 1..item.quantity loop
      gc := public._gift_code();
      insert into public.gift_cards (code, initial_kobo, balance_kobo, purchaser_email, recipient_email, message, expires_at)
      values (gc, item.unit_price_kobo, item.unit_price_kobo, o.contact_email, nullif(item.options->>'recipient_email',''), nullif(item.options->>'message',''), now() + interval '12 months');
      codes := codes || jsonb_build_array(jsonb_build_object('code', gc, 'amount', item.unit_price_kobo, 'recipient_email', item.options->>'recipient_email', 'message', item.options->>'message'));
    end loop;
  end loop;

  -- Routing. Custom orders wait for the proof; the 5-day clock starts when it is approved (later phase).
  select * into z from public.delivery_zones where id = o.delivery_zone_id;
  lead := case when o.express then 2 else coalesce(z.lead_days, 5) end;
  insert into public.order_events (order_id, status, note) values (o.id, 'paid', 'Payment confirmed');
  if o.has_custom then
    final := 'awaiting_proof';
    update public.custom_requests set status = 'awaiting_proof'
     where id in (select custom_request_id from public.order_items where order_id = o.id and custom_request_id is not null);
    update public.orders set status = final, paid_at = start_at, expires_at = null where id = o.id;
    insert into public.order_events (order_id, status, note) values (o.id, final, 'Waiting for your design proof');
  else
    final := 'paid';
    update public.orders set status = final, paid_at = start_at, expires_at = null, production_start_at = start_at, promised_by = start_at + make_interval(days => lead) where id = o.id;
  end if;

  return jsonb_build_object('ok', true, 'already', false, 'order_id', o.id, 'number', o.number, 'status', final, 'token', o.public_token, 'gift_cards', codes);
end $$;

-- ---------------------------------------------------------------- expiry
create or replace function public.checkout_cancel_expired(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o record; n int := 0;
begin
  for o in select id from public.orders where status = 'pending_payment' and expires_at is not null and expires_at < coalesce((p->>'now')::timestamptz, now()) for update skip locked loop
    perform public._release_order(o.id);
    update public.orders set status = 'cancelled' where id = o.id;
    update public.payments set status = 'abandoned' where order_id = o.id and status = 'initialised';
    insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', 'Not paid within 24 hours');
    n := n + 1;
  end loop;
  return jsonb_build_object('cancelled', n);
end $$;

-- ---------------------------------------------------------------- read an order (guest tracking, confirmation)
create or replace function public.checkout_get_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; ok boolean := false; phone_digits text;
begin
  select * into o from public.orders where number = upper(p->>'number');
  if not found then return null; end if;
  phone_digits := right(regexp_replace(coalesce(p->>'contact',''), '\D', '', 'g'), 10);
  ok := (coalesce(p->>'token','') <> '' and p->>'token' = o.public_token)
     or (p->>'profile_id' is not null and o.profile_id = (p->>'profile_id')::uuid)
     or (coalesce(p->>'contact','') <> '' and (lower(p->>'contact') = lower(o.contact_email)
          or (length(phone_digits) = 10 and phone_digits = right(regexp_replace(o.contact_phone, '\D', '', 'g'), 10))));
  if not ok then return null; end if;
  return jsonb_build_object(
    'id', o.id, 'number', o.number, 'status', o.status, 'has_custom', o.has_custom, 'contact_email', o.contact_email, 'contact_phone', o.contact_phone,
    'subtotal_kobo', o.subtotal_kobo, 'discount_kobo', o.discount_kobo, 'delivery_fee_kobo', o.delivery_fee_kobo, 'gift_wrap_kobo', o.gift_wrap_kobo,
    'surprise_note_kobo', o.surprise_note_kobo, 'express_kobo', o.express_kobo, 'ship_ready_first_kobo', o.ship_ready_first_kobo,
    'credit_used_kobo', o.credit_used_kobo, 'gift_card_used_kobo', o.gift_card_used_kobo, 'total_kobo', o.total_kobo,
    'address', o.address, 'delivery_zone_name', o.delivery_zone_name, 'is_gift', o.is_gift, 'gift_message', o.gift_message,
    'discount_code', o.discount_code, 'payment_reference', o.payment_reference, 'paid_at', o.paid_at,
    'production_start_at', o.production_start_at, 'promised_by', o.promised_by, 'delivered_at', o.delivered_at,
    'expires_at', o.expires_at, 'created_at', o.created_at, 'token', o.public_token,
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'name', i.name, 'options', i.options, 'selections', i.selections,
              'unit_price_kobo', i.unit_price_kobo, 'quantity', i.quantity, 'custom_request_id', i.custom_request_id, 'gift_message', i.gift_message) order by i.created_at), '[]'::jsonb)
              from public.order_items i where i.order_id = o.id),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('status', e.status, 'note', e.note, 'created_at', e.created_at) order by e.created_at), '[]'::jsonb)
              from public.order_events e where e.order_id = o.id)
  );
end $$;

-- Lock every function down to the service role.
do $$
declare f text;
begin
  foreach f in array array[
    'checkout_context(jsonb)','custom_request_create(jsonb)','checkout_custom_requests(jsonb)','checkout_create_order(jsonb)',
    'checkout_mark_paid(jsonb)','checkout_cancel_expired(jsonb)','checkout_get_order(jsonb)','_release_order(uuid)','_gift_code()']
  loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;

-- Cancel one unpaid order right now (e.g. the payment provider refused to start a transaction).
create or replace function public.checkout_cancel_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  select * into o from public.orders where id = (p->>'order_id')::uuid and status = 'pending_payment' for update;
  if not found then return jsonb_build_object('cancelled', false); end if;
  perform public._release_order(o.id);
  update public.orders set status = 'cancelled' where id = o.id;
  update public.payments set status = 'failed' where order_id = o.id and status = 'initialised';
  insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', coalesce(p->>'note', 'Cancelled'));
  return jsonb_build_object('cancelled', true);
end $$;
revoke all on function public.checkout_cancel_order(jsonb) from public, anon, authenticated;
grant execute on function public.checkout_cancel_order(jsonb) to service_role;

-- Live stock for every stocked variant (a few dozen rows), so quotes never rely on the cached catalogue for availability.
create or replace function public.checkout_stock(p jsonb) returns jsonb
language sql security definer stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'stock_qty', stock_qty, 'reserved_qty', reserved_qty)), '[]'::jsonb)
  from public.product_variants where stock_qty is not null
$$;
revoke all on function public.checkout_stock(jsonb) from public, anon, authenticated;
grant execute on function public.checkout_stock(jsonb) to service_role;

-- ================= supabase/migrations/0011_post_purchase.sql =================
-- Pemart 0011: accounts and post-purchase. Proof round trip, order status machine, reviews + store credit,
-- reminders, resuming payment. Same rules as 0010: one jsonb argument, SECURITY DEFINER, service role only.

alter table public.orders add column if not exists review_request_sent_at timestamptz;
alter table public.custom_requests add column if not exists revisions_paid int not null default 0,
                                   add column if not exists feedback jsonb not null default '[]'::jsonb;   -- [{version, note, at}]
alter table public.reviews add column if not exists credit_pending boolean not null default false,
                           add column if not exists moderated_at timestamptz;
alter table public.settings add column if not exists revision_fee_kobo bigint not null default 200000,
                            add column if not exists review_credit_kobo bigint not null default 200000;
alter table public.order_items drop constraint if exists order_items_kind_check;
alter table public.order_items add constraint order_items_kind_check check (kind in ('variant','bundle','gift_card','custom','revision'));
create unique index if not exists reviews_one_per_item on public.reviews(order_item_id) where order_item_id is not null;

-- ------------------------------------------------------------ status machine
create or replace function public._order_transition_ok(f text, t text) returns boolean language sql immutable as $$
  select case
    when f = t then false
    when t = 'cancelled' then f in ('paid','awaiting_proof','proof_sent','revision_requested','approved','in_production','quality_check','packed','reprint')
    when t = 'refunded' then f in ('paid','awaiting_proof','proof_sent','revision_requested','approved','in_production','quality_check','packed','out_for_delivery','delivered','reprint','cancelled')
    when t = 'in_production' then f in ('paid','approved','reprint')
    when t = 'quality_check' then f = 'in_production'
    when t = 'reprint' then f = 'quality_check'
    when t = 'packed' then f = 'quality_check'
    when t = 'out_for_delivery' then f = 'packed'
    when t = 'delivered' then f = 'out_for_delivery'
    else false end
$$;

create or replace function public.order_set_status(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  select * into o from public.orders where id = (p->>'order_id')::uuid for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public._order_transition_ok(o.status, p->>'to') then
    return jsonb_build_object('ok', false, 'error', 'bad_transition', 'from', o.status, 'to', p->>'to');
  end if;
  -- Production cannot start while a custom design is unapproved.
  if p->>'to' = 'in_production' and o.has_custom and o.status not in ('approved','reprint') then
    return jsonb_build_object('ok', false, 'error', 'proof_not_approved');
  end if;
  if p->>'to' in ('cancelled') then perform public._release_order(o.id); end if;
  update public.orders set status = p->>'to', delivered_at = case when p->>'to' = 'delivered' then now() else delivered_at end where id = o.id;
  insert into public.order_events (order_id, status, note, actor) values (o.id, p->>'to', p->>'note', (p->>'actor')::uuid);
  return jsonb_build_object('ok', true, 'order_id', o.id, 'number', o.number, 'token', o.public_token, 'email', o.contact_email, 'phone', o.contact_phone,
                            'status', p->>'to', 'promised_by', o.promised_by);
end $$;

-- ------------------------------------------------------------ digital orders finish instantly; payments found by reference
create or replace function public.checkout_mark_paid(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  oid uuid; o public.orders; pay public.payments; z public.delivery_zones; amb public.ambassadors; r jsonb; v public.product_variants;
  item record; lead int; start_at timestamptz := now(); final text; codes jsonb := '[]'::jsonb; gc text; i int; digital boolean;
begin
  -- Find the order through the PAYMENT reference (an order can have several over its life: see checkout_new_reference).
  select order_id into oid from public.payments where reference = p->>'reference';
  if oid is null then return jsonb_build_object('ok', false, 'error', 'unknown_reference'); end if;
  select * into o from public.orders where id = oid for update;
  select * into pay from public.payments where reference = p->>'reference' for update;

  if pay.status = 'success' or (o.status not in ('pending_payment','cancelled') and o.paid_at is not null) then
    -- Idempotency. (Also covers a second reference paying an order that is already settled: flagged for a refund.)
    if pay.status <> 'success' then
      update public.payments set status = 'success', verified_at = now(), raw_payload = p->'payload' where id = pay.id;
      update public.orders set payment_note = 'Paid twice (second reference ' || (p->>'reference') || '). Refund needed.' where id = o.id;
      insert into public.order_events (order_id, status, note) values (o.id, o.status, 'Duplicate payment received. Refund needed.');
      return jsonb_build_object('ok', true, 'already', true, 'duplicate_payment', true, 'order_id', o.id, 'number', o.number, 'status', o.status, 'token', o.public_token);
    end if;
    return jsonb_build_object('ok', true, 'already', true, 'order_id', o.id, 'number', o.number, 'status', o.status, 'token', o.public_token);
  end if;

  if (p->>'amount')::bigint is distinct from o.total_kobo or coalesce(p->>'currency','NGN') <> 'NGN' then
    update public.payments set status = 'failed', raw_payload = p->'payload' where id = pay.id;
    insert into public.order_events (order_id, status, note) values (o.id, o.status, 'Payment rejected: amount or currency mismatch');
    return jsonb_build_object('ok', false, 'error', 'amount_mismatch', 'order_id', o.id);
  end if;

  if o.status = 'cancelled' then
    begin
      for r in select * from jsonb_array_elements(o.reservations) loop
        select * into v from public.product_variants where id = (r->>'variant_id')::uuid for update;
        if v.stock_qty - v.reserved_qty < (r->>'qty')::int then raise exception 'out_of_stock'; end if;
        update public.product_variants set reserved_qty = reserved_qty + (r->>'qty')::int where id = v.id;
      end loop;
      if o.credit_used_kobo > 0 then update public.profiles set store_credit_kobo = store_credit_kobo - o.credit_used_kobo where id = o.profile_id and store_credit_kobo >= o.credit_used_kobo; if not found then raise exception 'credit'; end if; end if;
      if o.gift_card_used_kobo > 0 then update public.gift_cards set balance_kobo = balance_kobo - o.gift_card_used_kobo where id = o.gift_card_id and balance_kobo >= o.gift_card_used_kobo; if not found then raise exception 'gift'; end if; end if;
    exception when others then
      update public.payments set status = 'success', verified_at = now(), raw_payload = p->'payload' where id = pay.id;
      update public.orders set payment_note = 'Paid after the order expired and could not be restored. Refund needed.' where id = o.id;
      insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', 'Payment received after expiry; could not restore stock. Refund needed.');
      return jsonb_build_object('ok', true, 'needs_refund', true, 'order_id', o.id, 'number', o.number, 'status', 'cancelled', 'token', o.public_token);
    end;
  end if;

  update public.payments set status = 'success', verified_at = now(), raw_payload = p->'payload' where id = pay.id;
  update public.payments set status = 'abandoned' where order_id = o.id and id <> pay.id and status = 'initialised';

  for r in select * from jsonb_array_elements(o.reservations) loop
    update public.product_variants set stock_qty = stock_qty - (r->>'qty')::int, reserved_qty = greatest(0, reserved_qty - (r->>'qty')::int)
     where id = (r->>'variant_id')::uuid and stock_qty is not null;
  end loop;
  if o.discount_code_id is not null then update public.discount_codes set times_used = times_used + 1 where id = o.discount_code_id; end if;

  if o.ambassador_code is not null then
    select a.* into amb from public.ambassadors a where upper(a.code) = upper(o.ambassador_code);
    if found then
      insert into public.commissions (ambassador_id, order_id, amount_kobo, status)
      values (amb.id, o.id, round(o.subtotal_kobo * amb.commission_rate)::bigint, 'pending') on conflict (order_id) do nothing;
    end if;
  end if;

  for item in select * from public.order_items where order_id = o.id and kind = 'gift_card' loop
    for i in 1..item.quantity loop
      gc := public._gift_code();
      insert into public.gift_cards (code, initial_kobo, balance_kobo, purchaser_email, recipient_email, message, expires_at)
      values (gc, item.unit_price_kobo, item.unit_price_kobo, o.contact_email, nullif(item.options->>'recipient_email',''), nullif(item.options->>'message',''), now() + interval '12 months');
      codes := codes || jsonb_build_array(jsonb_build_object('code', gc, 'amount', item.unit_price_kobo, 'recipient_email', item.options->>'recipient_email', 'message', item.options->>'message'));
    end loop;
  end loop;

  -- A paid extra revision gives that design one more free revision.
  for item in select * from public.order_items where order_id = o.id and kind = 'revision' and custom_request_id is not null loop
    update public.custom_requests set revisions_paid = revisions_paid + item.quantity where id = item.custom_request_id;
  end loop;

  select * into z from public.delivery_zones where id = o.delivery_zone_id;
  lead := case when o.express then 2 else coalesce(z.lead_days, 5) end;
  digital := not exists (select 1 from public.order_items where order_id = o.id and kind not in ('gift_card','revision'));
  insert into public.order_events (order_id, status, note) values (o.id, 'paid', 'Payment confirmed');
  if digital then
    final := 'delivered';
    update public.orders set status = final, paid_at = start_at, delivered_at = start_at, expires_at = null where id = o.id;
    insert into public.order_events (order_id, status, note) values (o.id, final, 'Delivered by email');
  elsif o.has_custom then
    final := 'awaiting_proof';
    update public.custom_requests set status = 'awaiting_proof' where id in (select custom_request_id from public.order_items where order_id = o.id and kind = 'custom' and custom_request_id is not null);
    update public.orders set status = final, paid_at = start_at, expires_at = null where id = o.id;
    insert into public.order_events (order_id, status, note) values (o.id, final, 'Waiting for your design proof');
  else
    final := 'paid';
    update public.orders set status = final, paid_at = start_at, expires_at = null, production_start_at = start_at, promised_by = start_at + make_interval(days => lead) where id = o.id;
  end if;
  return jsonb_build_object('ok', true, 'already', false, 'order_id', o.id, 'number', o.number, 'status', final, 'token', o.public_token, 'gift_cards', codes, 'digital', digital);
end $$;

-- ------------------------------------------------------------ the proof round trip
create or replace function public._recompute_custom_order(p_order uuid) returns text
language plpgsql security definer set search_path = public as $$
declare o public.orders; z public.delivery_zones; total int; appr int; rev int; awa int; new_status text;
begin
  select * into o from public.orders where id = p_order for update;
  if o.status not in ('awaiting_proof','proof_sent','revision_requested') then return o.status; end if;
  select count(*), count(*) filter (where c.status = 'approved'), count(*) filter (where c.status = 'revision_requested'), count(*) filter (where c.status = 'awaiting_proof')
    into total, appr, rev, awa
    from public.custom_requests c join public.order_items i on i.custom_request_id = c.id where i.order_id = p_order and i.kind = 'custom';
  new_status := case when total > 0 and appr = total then 'approved' when rev > 0 then 'revision_requested' when awa > 0 then 'awaiting_proof' else 'proof_sent' end;
  if new_status <> o.status then
    update public.orders set status = new_status where id = p_order;
    insert into public.order_events (order_id, status, note) values (p_order, new_status,
      case new_status when 'approved' then 'Design approved. Your 5-day delivery clock has started.' when 'proof_sent' then 'Your design proof is ready' when 'revision_requested' then 'Revision requested' else null end);
  end if;
  -- The 5-day clock starts only when EVERY custom design in the order is approved.
  if new_status = 'approved' and o.production_start_at is null then
    select * into z from public.delivery_zones where id = o.delivery_zone_id;
    update public.orders set production_start_at = now(), promised_by = now() + make_interval(days => coalesce(z.lead_days, 5)) where id = p_order;
  end if;
  return new_status;
end $$;

create or replace function public.proof_send(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.custom_requests; o public.orders; v int; st text;
begin
  select * into c from public.custom_requests where id = (p->>'custom_request_id')::uuid for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if c.status not in ('awaiting_proof','revision_requested') then return jsonb_build_object('ok', false, 'error', 'not_awaiting_proof', 'status', c.status); end if;
  select o2.* into o from public.orders o2 join public.order_items i on i.order_id = o2.id
   where i.custom_request_id = c.id and i.kind = 'custom' and o2.status <> 'cancelled' order by o2.created_at desc limit 1;
  if not found then return jsonb_build_object('ok', false, 'error', 'no_order'); end if;
  v := jsonb_array_length(c.proofs) + 1;
  update public.custom_requests set status = 'proof_sent',
    proofs = proofs || jsonb_build_array(jsonb_build_object('version', v, 'path', p->>'path', 'message', p->>'message', 'sent_at', now()))
   where id = c.id;
  st := public._recompute_custom_order(o.id);
  insert into public.order_events (order_id, status, note, actor) values (o.id, st, 'Proof version ' || v || ' sent', (p->>'actor')::uuid);
  return jsonb_build_object('ok', true, 'version', v, 'order_id', o.id, 'number', o.number, 'token', o.public_token, 'email', o.contact_email, 'phone', o.contact_phone, 'order_status', st);
end $$;

create or replace function public.proof_respond(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.custom_requests; o public.orders; st text; allowance int;
begin
  select * into c from public.custom_requests where id = (p->>'custom_request_id')::uuid for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  select o2.* into o from public.orders o2 join public.order_items i on i.order_id = o2.id
   where i.custom_request_id = c.id and i.kind = 'custom' and o2.status <> 'cancelled' order by o2.created_at desc limit 1;
  if not found or not ((coalesce(p->>'token','') <> '' and p->>'token' = o.public_token) or (p->>'profile_id' is not null and o.profile_id = (p->>'profile_id')::uuid)) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  if c.status <> 'proof_sent' then return jsonb_build_object('ok', false, 'error', 'no_proof_waiting', 'status', c.status); end if;

  if p->>'decision' = 'approve' then
    update public.custom_requests set status = 'approved', approved_at = now() where id = c.id;
  elsif p->>'decision' = 'revise' then
    allowance := 1 + c.revisions_paid;
    if c.revisions_used >= allowance then return jsonb_build_object('ok', false, 'error', 'paid_revision_required', 'custom_request_id', c.id); end if;
    if length(btrim(coalesce(p->>'note',''))) < 3 then return jsonb_build_object('ok', false, 'error', 'note_required'); end if;
    update public.custom_requests set status = 'revision_requested', revisions_used = revisions_used + 1,
      feedback = feedback || jsonb_build_array(jsonb_build_object('version', jsonb_array_length(c.proofs), 'note', left(p->>'note', 1000), 'at', now()))
     where id = c.id;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_decision');
  end if;
  st := public._recompute_custom_order(o.id);
  insert into public.order_events (order_id, status, note) values (o.id, st, case when p->>'decision' = 'approve' then 'Design approved by customer' else 'Customer asked for a revision' end);
  select * into o from public.orders where id = o.id;
  return jsonb_build_object('ok', true, 'decision', p->>'decision', 'order_status', st, 'order_id', o.id, 'number', o.number, 'token', o.public_token, 'email', o.contact_email,
                            'promised_by', o.promised_by, 'production_started', o.production_start_at is not null);
end $$;

-- Payment can be restarted: the old reference stays valid (a late payment on it is still matched), a new one is issued.
create or replace function public.checkout_new_reference(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  select * into o from public.orders where number = upper(p->>'number') and public_token = p->>'token' and status = 'pending_payment' and (expires_at is null or expires_at > now()) for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_payable'); end if;
  update public.payments set status = 'abandoned' where order_id = o.id and status = 'initialised';
  insert into public.payments (order_id, provider, reference, amount_kobo, currency, status) values (o.id, 'paystack', p->>'reference', o.total_kobo, 'NGN', 'initialised');
  update public.orders set payment_reference = p->>'reference' where id = o.id;
  return jsonb_build_object('ok', true, 'order_id', o.id, 'number', o.number, 'total', o.total_kobo, 'email', o.contact_email, 'token', o.public_token);
end $$;

-- ------------------------------------------------------------ reviews and store credit
create or replace function public._grant_review_credit(p_review uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare rv public.reviews; o public.orders; pid uuid; amt bigint;
begin
  select * into rv from public.reviews where id = p_review for update;
  if rv.credit_issued or cardinality(rv.photo_urls) = 0 then return false; end if;
  select o2.* into o from public.orders o2 join public.order_items i on i.order_id = o2.id where i.id = rv.order_item_id;
  pid := o.profile_id;
  if pid is null then select id into pid from public.profiles where lower(email) = lower(o.contact_email) limit 1; end if;
  select coalesce((select review_credit_kobo from public.settings limit 1), 200000) into amt;
  if pid is null then update public.reviews set credit_pending = true where id = rv.id; return false; end if;
  update public.profiles set store_credit_kobo = store_credit_kobo + amt where id = pid;
  update public.reviews set credit_issued = true, credit_pending = false where id = rv.id;
  return true;
end $$;

create or replace function public._claim_pending_credit(p_profile uuid, p_email text) returns void
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select rv.id from public.reviews rv join public.order_items i on i.id = rv.order_item_id join public.orders o on o.id = i.order_id
            where rv.credit_pending and not rv.credit_issued and rv.status = 'approved' and lower(o.contact_email) = lower(p_email) loop
    perform public._grant_review_credit(r.id);
  end loop;
end $$;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'))
  on conflict (id) do nothing;
  perform public._claim_pending_credit(new.id, new.email);
  return new;
end $$;

create or replace function public.review_submit(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; i public.order_items; pid uuid; rid uuid;
begin
  select * into o from public.orders where number = upper(p->>'number');
  if not found or not ((coalesce(p->>'token','') <> '' and p->>'token' = o.public_token) or (p->>'profile_id' is not null and o.profile_id = (p->>'profile_id')::uuid)) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed'); end if;
  if o.status <> 'delivered' then return jsonb_build_object('ok', false, 'error', 'not_delivered'); end if;
  select * into i from public.order_items where id = (p->>'order_item_id')::uuid and order_id = o.id;
  if not found then return jsonb_build_object('ok', false, 'error', 'item_not_found'); end if;
  if i.kind = 'variant' then select product_id into pid from public.product_variants where id = i.variant_id;
  elsif i.kind = 'bundle' then pid := nullif(i.selections->0->>'productId', '')::uuid; end if;
  if pid is null then return jsonb_build_object('ok', false, 'error', 'not_reviewable'); end if;
  if exists (select 1 from public.reviews where order_item_id = i.id) then return jsonb_build_object('ok', false, 'error', 'already_reviewed'); end if;
  if (p->>'rating')::int not between 1 and 5 then return jsonb_build_object('ok', false, 'error', 'bad_rating'); end if;
  insert into public.reviews (product_id, order_item_id, profile_id, display_name, rating, text, photo_urls, status)
  values (pid, i.id, o.profile_id, left(nullif(btrim(p->>'display_name'), ''), 60), (p->>'rating')::int, left(nullif(btrim(p->>'text'), ''), 1500),
          coalesce(array(select jsonb_array_elements_text(p->'photo_urls')), '{}'), 'pending') returning id into rid;
  return jsonb_build_object('ok', true, 'id', rid);
end $$;

create or replace function public.review_moderate(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare rv public.reviews; granted boolean := false;
begin
  select * into rv from public.reviews where id = (p->>'review_id')::uuid for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if p->>'decision' = 'approve' then
    update public.reviews set status = 'approved', moderated_at = now() where id = rv.id;
    granted := public._grant_review_credit(rv.id);   -- only photo reviews earn credit, and only once
  elsif p->>'decision' = 'reject' then
    update public.reviews set status = 'rejected', moderated_at = now() where id = rv.id;
  else return jsonb_build_object('ok', false, 'error', 'bad_decision'); end if;
  return jsonb_build_object('ok', true, 'credit_granted', granted);
end $$;

-- ------------------------------------------------------------ reminders (called hourly)
create or replace function public.reminders_due(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare abandoned jsonb; reviews jsonb;
begin
  with u as (
    update public.orders set abandoned_email_sent_at = now()
     where status = 'pending_payment' and created_at <= now() - interval '1 hour' and (expires_at is null or expires_at > now()) and abandoned_email_sent_at is null
     returning number, public_token, contact_email, total_kobo)
  select coalesce(jsonb_agg(jsonb_build_object('number', number, 'token', public_token, 'email', contact_email, 'total', total_kobo)), '[]'::jsonb) into abandoned from u;
  with u as (
    update public.orders set review_request_sent_at = now()
     where status = 'delivered' and delivered_at <= now() - interval '3 days' and review_request_sent_at is null
       and exists (select 1 from public.order_items i where i.order_id = orders.id and i.kind in ('variant','bundle'))
     returning number, public_token, contact_email)
  select coalesce(jsonb_agg(jsonb_build_object('number', number, 'token', public_token, 'email', contact_email)), '[]'::jsonb) into reviews from u;
  return jsonb_build_object('abandoned', abandoned, 'reviews', reviews);
end $$;

-- ------------------------------------------------------------ account
create or replace function public.profile_get(p jsonb) returns jsonb language sql security definer stable set search_path = public as $$
  select to_jsonb(x) from (select id, email, full_name, phone, role, store_credit_kobo from public.profiles where id = (p->>'id')::uuid) x
$$;

create or replace function public.account_overview(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare pr public.profiles; pid uuid := (p->>'profile_id')::uuid;
begin
  select * into pr from public.profiles where id = pid;
  if not found then return null; end if;
  return jsonb_build_object(
    'profile', jsonb_build_object('id', pr.id, 'email', pr.email, 'full_name', pr.full_name, 'phone', pr.phone, 'role', pr.role, 'store_credit_kobo', pr.store_credit_kobo),
    'orders', (select coalesce(jsonb_agg(jsonb_build_object(
        'number', o.number, 'status', o.status, 'total_kobo', o.total_kobo, 'created_at', o.created_at, 'promised_by', o.promised_by, 'has_custom', o.has_custom,
        'token', o.public_token, 'delivered_at', o.delivered_at,
        'reviewable', exists (select 1 from public.order_items i where i.order_id = o.id and i.kind in ('variant','bundle') and not exists (select 1 from public.reviews r where r.order_item_id = i.id)),
        'items', (select coalesce(jsonb_agg(i.name order by i.created_at), '[]'::jsonb) from public.order_items i where i.order_id = o.id),
        'proofs_waiting', (select count(*) from public.custom_requests c join public.order_items i on i.custom_request_id = c.id where i.order_id = o.id and i.kind = 'custom' and c.status = 'proof_sent')
      ) order by o.created_at desc), '[]'::jsonb) from public.orders o where o.profile_id = pid or lower(o.contact_email) = lower(pr.email)),
    'addresses', (select coalesce(jsonb_agg(to_jsonb(a) order by a.is_default desc, a.created_at), '[]'::jsonb) from public.addresses a where a.profile_id = pid),
    'wishlist', (select coalesce(jsonb_agg(w.product_id), '[]'::jsonb) from public.wishlist_items w where w.profile_id = pid));
end $$;

create or replace function public.address_save(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare pid uuid := (p->>'profile_id')::uuid; zid uuid; aid uuid;
begin
  select id into zid from public.delivery_zones where (p->>'state') = any(states) limit 1;
  if p->>'id' is not null then
    update public.addresses set recipient = p->>'recipient', phone = p->>'phone', line1 = p->>'line1', area = p->>'area', city = p->>'city', state = p->>'state', delivery_zone_id = zid
     where id = (p->>'id')::uuid and profile_id = pid returning id into aid;
    if aid is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  else
    insert into public.addresses (profile_id, recipient, phone, line1, area, city, state, delivery_zone_id, is_default)
    values (pid, p->>'recipient', p->>'phone', p->>'line1', p->>'area', p->>'city', p->>'state', zid, not exists (select 1 from public.addresses where profile_id = pid)) returning id into aid;
  end if;
  if coalesce((p->>'is_default')::boolean, false) then
    update public.addresses set is_default = (id = aid) where profile_id = pid;
  end if;
  return jsonb_build_object('ok', true, 'id', aid);
end $$;

create or replace function public.address_delete(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare pid uuid := (p->>'profile_id')::uuid; was_default boolean;
begin
  delete from public.addresses where id = (p->>'id')::uuid and profile_id = pid returning is_default into was_default;
  if was_default then update public.addresses set is_default = true where id = (select id from public.addresses where profile_id = pid order by created_at limit 1); end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.wishlist_toggle(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  delete from public.wishlist_items where profile_id = (p->>'profile_id')::uuid and product_id = (p->>'product_id')::uuid;
  get diagnostics n = row_count;
  if n = 0 then insert into public.wishlist_items (profile_id, product_id) values ((p->>'profile_id')::uuid, (p->>'product_id')::uuid); return jsonb_build_object('on', true); end if;
  return jsonb_build_object('on', false);
end $$;

create or replace function public.profile_update(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  update public.profiles set full_name = left(nullif(btrim(p->>'full_name'), ''), 80), phone = left(nullif(btrim(p->>'phone'), ''), 30) where id = (p->>'profile_id')::uuid;
  return jsonb_build_object('ok', true);
end $$;

-- ------------------------------------------------------------ order lookup now includes proofs and review state
create or replace function public.checkout_get_order(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o public.orders; ok boolean := false; phone_digits text;
begin
  select * into o from public.orders where number = upper(p->>'number');
  if not found then return null; end if;
  phone_digits := right(regexp_replace(coalesce(p->>'contact',''), '\D', '', 'g'), 10);
  ok := (coalesce(p->>'token','') <> '' and p->>'token' = o.public_token)
     or (p->>'profile_id' is not null and o.profile_id = (p->>'profile_id')::uuid)
     or (coalesce(p->>'contact','') <> '' and (lower(p->>'contact') = lower(o.contact_email)
          or (length(phone_digits) = 10 and phone_digits = right(regexp_replace(o.contact_phone, '\D', '', 'g'), 10))));
  if not ok then return null; end if;
  return jsonb_build_object(
    'id', o.id, 'number', o.number, 'status', o.status, 'has_custom', o.has_custom, 'contact_email', o.contact_email, 'contact_phone', o.contact_phone,
    'subtotal_kobo', o.subtotal_kobo, 'discount_kobo', o.discount_kobo, 'delivery_fee_kobo', o.delivery_fee_kobo, 'gift_wrap_kobo', o.gift_wrap_kobo,
    'surprise_note_kobo', o.surprise_note_kobo, 'express_kobo', o.express_kobo, 'ship_ready_first_kobo', o.ship_ready_first_kobo,
    'credit_used_kobo', o.credit_used_kobo, 'gift_card_used_kobo', o.gift_card_used_kobo, 'total_kobo', o.total_kobo,
    'address', o.address, 'delivery_zone_name', o.delivery_zone_name, 'is_gift', o.is_gift, 'gift_message', o.gift_message,
    'discount_code', o.discount_code, 'payment_reference', o.payment_reference, 'paid_at', o.paid_at,
    'production_start_at', o.production_start_at, 'promised_by', o.promised_by, 'delivered_at', o.delivered_at,
    'expires_at', o.expires_at, 'created_at', o.created_at, 'token', o.public_token, 'profile_id', o.profile_id,
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'name', i.name, 'options', i.options, 'selections', i.selections,
              'unit_price_kobo', i.unit_price_kobo, 'quantity', i.quantity, 'custom_request_id', i.custom_request_id, 'gift_message', i.gift_message,
              'review_status', (select r.status from public.reviews r where r.order_item_id = i.id)) order by i.created_at), '[]'::jsonb)
              from public.order_items i where i.order_id = o.id),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('status', e.status, 'note', e.note, 'created_at', e.created_at) order by e.created_at), '[]'::jsonb)
              from public.order_events e where e.order_id = o.id),
    'custom_requests', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'tier', c.tier, 'product_type', c.product_type, 'colour', c.colour, 'status', c.status,
              'proofs', c.proofs, 'feedback', c.feedback, 'revisions_used', c.revisions_used, 'revisions_paid', c.revisions_paid, 'text_fields', c.text_fields,
              'type_style', c.type_style, 'notes', c.notes, 'print_positions', c.print_positions, 'design_slug', (select d.slug from public.designs d where d.id = c.design_id)) order by c.created_at), '[]'::jsonb)
              from public.custom_requests c join public.order_items i on i.custom_request_id = c.id where i.order_id = o.id and i.kind = 'custom')
  );
end $$;

create or replace function public.checkout_custom_requests(p jsonb) returns jsonb
language sql security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'tier', c.tier, 'product_type', c.product_type, 'colour', c.colour, 'status', c.status,
    'text_fields', c.text_fields, 'type_style', c.type_style, 'design_id', c.design_id, 'print_positions', c.print_positions,
    'in_use', exists (select 1 from public.order_items oi join public.orders o on o.id = oi.order_id
                      where oi.custom_request_id = c.id and oi.kind = 'custom' and o.status not in ('cancelled'))
  )), '[]'::jsonb)
  from public.custom_requests c
  where c.id in (select (jsonb_array_elements_text(p->'ids'))::uuid)
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'order_set_status(jsonb)','proof_send(jsonb)','proof_respond(jsonb)','checkout_new_reference(jsonb)','review_submit(jsonb)','review_moderate(jsonb)',
    'reminders_due(jsonb)','profile_get(jsonb)','account_overview(jsonb)','address_save(jsonb)','address_delete(jsonb)','wishlist_toggle(jsonb)','profile_update(jsonb)',
    'checkout_get_order(jsonb)','checkout_custom_requests(jsonb)','checkout_mark_paid(jsonb)','_recompute_custom_order(uuid)','_grant_review_credit(uuid)',
    '_claim_pending_credit(uuid,text)','_order_transition_ok(text,text)']
  loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;

-- ================= supabase/migrations/0012_admin.sql =================
-- Pemart 0012: admin. Every function takes ONE jsonb argument containing `actor` (the signed-in profile id,
-- verified by the app) and re-checks that profile's role INSIDE the database, on top of the page and server-action
-- gates in the app and the RLS policies on the tables. Service role only.

alter table public.order_items drop constraint if exists order_items_kind_check;
alter table public.order_items add constraint order_items_kind_check check (kind in ('variant','bundle','gift_card','custom','revision','bulk'));

create or replace function public._require(actor uuid, roles text[]) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if actor is null or not (coalesce((select role from public.profiles where id = actor), 'none') = any(roles)) then
    raise exception 'forbidden';
  end if;
end $$;

-- Generic, whitelisted row saver. Only columns in `allowed` AND present in the JSON are written, so absent keys
-- keep their defaults (insert) or their current values (update).
create or replace function public._save_row(tbl text, p jsonb, allowed text[]) returns uuid
language plpgsql set search_path = public as $$
declare cols text[]; cl text; sl text; rid uuid := nullif(p->>'id','')::uuid; res uuid;
begin
  select coalesce(array_agg(k), '{}') into cols from jsonb_object_keys(p) k where k = any(allowed);
  if coalesce(array_length(cols,1), 0) = 0 then raise exception 'nothing_to_save'; end if;
  select string_agg(quote_ident(c), ', ') into cl from unnest(cols) c;
  if rid is null then
    execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1) returning id', tbl, cl, cl, tbl) into res using p;
  else
    select string_agg(format('%I = r.%I', c, c), ', ') into sl from unnest(cols) c;
    execute format('update public.%I t set %s from jsonb_populate_record(null::public.%I, $1) r where t.id = $2 returning t.id', tbl, sl, tbl) into res using p, rid;
    if res is null then raise exception 'not_found'; end if;
  end if;
  return res;
end $$;

-- ------------------------------------------------------------ public catalogue as one document (dev mode + fixture export)
create or replace function public.catalogue_export(p jsonb default '{}'::jsonb) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'collections', (select coalesce(jsonb_agg(to_jsonb(c) - 'search' order by c.sort_order), '[]') from public.collections c where c.is_active),
    'designs', (select coalesce(jsonb_agg(to_jsonb(d) order by d.name), '[]') from public.designs d where d.is_active),
    'products', (select coalesce(jsonb_agg((to_jsonb(p) - 'search') || jsonb_build_object(
        'product_variants', (select coalesce(jsonb_agg(to_jsonb(v) - 'image_ids' order by v.sku), '[]') from public.product_variants v where v.product_id = p.id and v.is_active),
        'product_images', (select coalesce(jsonb_agg(to_jsonb(i) order by i.sort_order), '[]') from public.product_images i where i.product_id = p.id)) order by p.name), '[]')
      from public.products p where p.is_active),
    'bundles', (select coalesce(jsonb_agg(to_jsonb(b) || jsonb_build_object('bundle_slots', (select coalesce(jsonb_agg(to_jsonb(s) order by s.sort_order), '[]') from public.bundle_slots s where s.bundle_id = b.id)) order by b.sort_order), '[]')
      from public.bundles b where b.is_active),
    'zones', (select coalesce(jsonb_agg(to_jsonb(z) order by z.sort_order), '[]') from public.delivery_zones z))
$$;
create or replace function public.settings_public(p jsonb default '{}'::jsonb) returns jsonb language sql stable security definer set search_path = public as $$
  select to_jsonb(s) - 'id' from public.settings s limit 1
$$;

-- ------------------------------------------------------------ overview
create or replace function public.admin_overview(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare actor uuid := (p->>'actor')::uuid; is_admin boolean; today date := (now() at time zone 'Africa/Lagos')::date; wk date := date_trunc('week', now() at time zone 'Africa/Lagos')::date;
  rev jsonb := null; week_orders int; week_rev bigint; created int; paid_created int;
begin
  perform public._require(actor, array['staff','admin']);
  is_admin := public._require_is_admin(actor);
  if is_admin then
    select count(*), coalesce(sum(total_kobo),0) into week_orders, week_rev from public.orders
      where paid_at is not null and status not in ('cancelled','refunded') and (paid_at at time zone 'Africa/Lagos')::date >= wk;
    select count(*), count(*) filter (where paid_at is not null) into created, paid_created from public.orders where created_at >= now() - interval '7 days';
    rev := jsonb_build_object(
      'today_orders', (select count(*) from public.orders where paid_at is not null and status not in ('cancelled','refunded') and (paid_at at time zone 'Africa/Lagos')::date = today),
      'today_revenue', (select coalesce(sum(total_kobo),0) from public.orders where paid_at is not null and status not in ('cancelled','refunded') and (paid_at at time zone 'Africa/Lagos')::date = today),
      'week_orders', week_orders, 'week_revenue', week_rev,
      'aov', case when week_orders > 0 then round(week_rev::numeric / week_orders)::bigint else 0 end,
      'bundle_share', case when week_orders > 0 then (select round(100.0 * count(*) filter (where has_bundle) / count(*)) from public.orders where paid_at is not null and status not in ('cancelled','refunded') and (paid_at at time zone 'Africa/Lagos')::date >= wk) else 0 end,
      'conversion', case when created > 0 then round(100.0 * paid_created / created) else 0 end, 'checkouts_started', created, 'checkouts_paid', paid_created);
  end if;
  return jsonb_build_object(
    'revenue', rev,
    'due_48h', (select count(*) from public.orders where promised_by between now() and now() + interval '48 hours' and status in ('paid','approved','in_production','quality_check','packed','reprint','out_for_delivery')),
    'at_risk', (select coalesce(jsonb_agg(x), '[]') from (select number, status, promised_by, contact_email, address->>'recipient' as recipient from public.orders
        where promised_by <= now() + interval '24 hours' and status in ('paid','approved','in_production','quality_check','reprint') order by promised_by limit 12) x),
    'proofs_waiting', (select count(*) from public.custom_requests where status in ('awaiting_proof','revision_requested')),
    'proofs_overdue', (select count(*) from public.custom_requests c join public.order_items i on i.custom_request_id = c.id and i.kind = 'custom' join public.orders o on o.id = i.order_id
        where c.status in ('awaiting_proof','revision_requested') and o.paid_at is not null
          and now() > coalesce((select (c.feedback->-1->>'at')::timestamptz where c.status = 'revision_requested'), o.paid_at) + make_interval(hours => case c.tier when 'personalise' then 12 when 'text_design' then 24 else 48 end)),
    'low_stock', (select coalesce(jsonb_agg(x), '[]') from (select v.id, p.name as product, v.sku, v.colour, v.size, v.option, v.stock_qty - v.reserved_qty as available
        from public.product_variants v join public.products p on p.id = v.product_id where v.stock_qty is not null and v.is_active and p.is_active and v.stock_qty - v.reserved_qty <= 5
        order by v.stock_qty - v.reserved_qty, p.name limit 12) x),
    'new_quotes', (select count(*) from public.bulk_quotes where status = 'new'),
    'pending_reviews', (select count(*) from public.reviews where status = 'pending'),
    'refunds_needed', (select count(*) from public.orders where payment_note ilike '%refund needed%' and status not in ('refunded')));
end $$;

create or replace function public._require_is_admin(actor uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select role = 'admin' from public.profiles where id = actor), false)
$$;

-- ------------------------------------------------------------ orders
create or replace function public.admin_orders_list(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare actor uuid := (p->>'actor')::uuid; q text := nullif(btrim(p->>'q'), ''); digits text; pg int := greatest(1, coalesce((p->>'page')::int, 1)); per int := least(100, greatest(1, coalesce((p->>'per_page')::int, 25)));
  statuses text[] := coalesce(array(select jsonb_array_elements_text(p->'status')), '{}'); total int; rows jsonb;
begin
  perform public._require(actor, array['staff','admin']);
  digits := right(regexp_replace(coalesce(q,''), '\D', '', 'g'), 10);
  with f as (
    select o.* from public.orders o
     where (q is null or o.number ilike '%' || q || '%' or lower(o.contact_email) like '%' || lower(q) || '%' or lower(o.address->>'recipient') like '%' || lower(q) || '%'
            or (length(digits) >= 6 and regexp_replace(o.contact_phone, '\D', '', 'g') like '%' || digits || '%'))
       and (cardinality(statuses) = 0 or o.status = any(statuses))
       and (nullif(p->>'zone','') is null or o.delivery_zone_name = p->>'zone')
       and (p->>'custom' is null or p->>'custom' = '' or o.has_custom = (p->>'custom')::boolean)
       and (nullif(p->>'promised_from','') is null or o.promised_by >= (p->>'promised_from')::date)
       and (nullif(p->>'promised_to','') is null or o.promised_by < (p->>'promised_to')::date + 1)
       and (coalesce((p->>'include_unpaid')::boolean, false) or o.status <> 'pending_payment' or cardinality(statuses) > 0))
  select (select count(*) from f),
         (select coalesce(jsonb_agg(r order by (r->>'created_at') desc), '[]') from (
            select jsonb_build_object('id', f.id, 'number', f.number, 'status', f.status, 'created_at', f.created_at, 'paid_at', f.paid_at, 'promised_by', f.promised_by,
              'total_kobo', f.total_kobo, 'email', f.contact_email, 'phone', f.contact_phone, 'recipient', f.address->>'recipient', 'zone', f.delivery_zone_name,
              'has_custom', f.has_custom, 'has_bundle', f.has_bundle, 'express', f.express,
              'at_risk', f.promised_by <= now() + interval '24 hours' and f.status in ('paid','approved','in_production','quality_check','reprint'),
              'items', (select coalesce(jsonb_agg(i.name order by i.created_at), '[]') from public.order_items i where i.order_id = f.id)) r
            from f order by f.created_at desc limit per offset (pg - 1) * per) s)
    into total, rows;
  return jsonb_build_object('total', total, 'page', pg, 'per_page', per, 'rows', rows);
end $$;

create or replace function public.admin_order_get(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare actor uuid := (p->>'actor')::uuid; o public.orders;
begin
  perform public._require(actor, array['staff','admin']);
  select * into o from public.orders where number = upper(p->>'number');
  if not found then return null; end if;
  return to_jsonb(o) - 'reservations' || jsonb_build_object(
    'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.created_at), '[]') from public.order_items i where i.order_id = o.id),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('status', e.status, 'note', e.note, 'created_at', e.created_at, 'actor', (select coalesce(full_name, email) from public.profiles where id = e.actor)) order by e.created_at), '[]') from public.order_events e where e.order_id = o.id),
    'payments', (select coalesce(jsonb_agg(jsonb_build_object('reference', pay.reference, 'amount_kobo', pay.amount_kobo, 'status', pay.status, 'verified_at', pay.verified_at, 'created_at', pay.created_at) order by pay.created_at), '[]') from public.payments pay where pay.order_id = o.id),
    'custom_requests', (select coalesce(jsonb_agg(to_jsonb(c) || jsonb_build_object('design_slug', (select d.slug from public.designs d where d.id = c.design_id), 'item_id', i.id) order by c.created_at), '[]')
        from public.custom_requests c join public.order_items i on i.custom_request_id = c.id and i.kind = 'custom' where i.order_id = o.id),
    'commission', (select to_jsonb(cm) from public.commissions cm where cm.order_id = o.id),
    'customer', (select jsonb_build_object('id', pr.id, 'name', pr.full_name, 'store_credit_kobo', pr.store_credit_kobo) from public.profiles pr where pr.id = o.profile_id));
end $$;

create or replace function public.admin_order_note(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform public._require((p->>'actor')::uuid, array['staff','admin']);
  update public.orders set notes = left(p->>'notes', 4000) where id = (p->>'order_id')::uuid;
  insert into public.order_events (order_id, status, note, actor) select id, status, 'Internal note updated', (p->>'actor')::uuid from public.orders where id = (p->>'order_id')::uuid;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.admin_set_status(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform public._require((p->>'actor')::uuid, array['staff','admin']);
  return public.order_set_status(p);
end $$;

create or replace function public.admin_proof_send(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
